export type ParsedIssueAttestationInstruction<
  TProgram extends string = typeof SEAL_REGISTRY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    authority: TAccountMetas[0];
    config: TAccountMetas[1];
    auditor: TAccountMetas[2];
    attestation: TAccountMetas[3];
    targetProgram: TAccountMetas[4];
    targetProgramdata: TAccountMetas[5];
    /** Fresh keypair for the Core certificate. */
    asset: TAccountMetas[6];
    collection: TAccountMetas[7];
    certOwner: TAccountMetas[8];
    mplCoreProgram: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
  };
  data: IssueAttestationInstructionData;
};

export function parseIssueAttestationInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedIssueAttestationInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      config: getNextAccount(),
      auditor: getNextAccount(),
      attestation: getNextAccount(),
      targetProgram: getNextAccount(),
      targetProgramdata: getNextAccount(),
      asset: getNextAccount(),
      collection: getNextAccount(),
      certOwner: getNextAccount(),
      mplCoreProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getIssueAttestationInstructionDataDecoder().decode(instruction.data),
  };
}
